from pathlib import Path
import json

ROOT = Path(__file__).resolve().parents[1]
out = ROOT / "throw-analysis"
pred = json.loads((out / "predictions.json").read_text())
evaluation = json.loads((out / "evaluation.json").read_text())
target = json.loads((out / "target-analysis.json").read_text())
ref = json.loads((out / "reference.json").read_text())
body = r"""<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Lancers et intention · Expérience continue</title><style>
:root{--bg:#f3f1e9;--ink:#142c35;--teal:#006f67;--line:#d6ded4;--muted:#546c70}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:17px/1.55 system-ui,sans-serif}main{max-width:1300px;margin:auto;padding:36px 4vw 70px}h1{font:normal clamp(40px,6vw,70px)/1.05 Georgia,serif;letter-spacing:-2px;max-width:900px}h2{font:normal 36px/1.15 Georgia,serif;margin:0 0 20px}h3{margin:0 0 12px;font-size:20px}p{max-width:1000px}a{color:var(--teal);text-underline-offset:4px}.eyebrow{font-size:12px;letter-spacing:2px;text-transform:uppercase;font-weight:750;color:var(--teal)}.lead{font-size:23px;color:var(--muted);max-width:950px}.stats,.three{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.card{padding:24px;border:1px solid var(--line);background:#fffef9;border-radius:10px}.stat{font:55px/1.2 Georgia,serif;display:block}.card p{margin-bottom:0}.dark{background:var(--ink);color:white}.dark .eyebrow{color:#d7ed9c}.note{border-left:4px solid var(--teal);background:#e6ece2;padding:17px 22px;margin:24px 0}.small{font-size:13px;color:var(--muted)}section{border-top:1px solid var(--line);padding-top:40px;margin-top:40px}.video-wrap{position:relative;background:#111;border-radius:8px;overflow:hidden}video{width:100%;display:block}canvas{position:absolute;inset:0;width:100%;height:100%;pointer-events:none}.controls{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:15px 0}button,select{font:inherit;color:var(--ink);padding:10px 14px;border:1px solid var(--line);border-radius:6px;background:#fffef9;cursor:pointer}button:hover{background:#e1ebda}button:focus-visible,a:focus-visible,select:focus-visible{outline:3px solid #be902e;outline-offset:2px}input[type=range]{flex:1;min-width:130px;accent-color:var(--teal)}.events{display:flex;gap:8px;flex-wrap:wrap;margin:18px 0}.events button{min-width:66px;border-bottom:4px solid #b54032}.events button.yellow{border-bottom-color:#dda816}.events button.active{background:var(--ink);color:white}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.clock{font-variant-numeric:tabular-nums}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;font-size:14px}th,td{text-align:left;padding:12px;border-bottom:1px solid var(--line)}th{color:var(--muted)}details{border-top:1px solid var(--line);padding:16px 0}summary{cursor:pointer;font-weight:650}code{font-size:14px}img{max-width:100%}.badge{padding:4px 8px;background:#e0eade;border-radius:15px;font-size:12px}footer{margin-top:40px;font-size:13px;color:var(--muted)}@media(max-width:700px){.stats,.three,.grid{grid-template-columns:1fr}main{padding:25px 5vw}h2{font-size:30px}.lead{font-size:20px}.stat{font-size:45px}.controls{font-size:14px}table{min-width:540px}}@media print{video,canvas,.controls,.events{display:none}body{background:white}section{break-before:page}.card{break-inside:avoid}}
</style></head><body><main><a href="../upload.html">← Prototype</a><p class="eyebrow">Canada–Corée · Curling en fauteuil roulant · Expérience de développement</p><h1>Repérer les lancers.<br>Ne pas confondre visée et destination.</h1><p class="lead">16 passages de pierres retrouvés dans une séquence continue de 18 min 30 s. Une première association entre lancer, balai de visée et pierre à l’arrivée.</p><div class="stats"><div class="card"><span class="stat" id="detected">16 / 16</span><p>Événements de référence retrouvés.</p></div><div class="card"><span class="stat">0 / 0</span><p>Faux événements / lancers manqués dans cette séquence.</p></div><div class="card dark"><span class="eyebrow">Score d’exécution</span><span class="stat" style="font-size:40px">Indisponible</span><p>Le balai observé indique la visée. La destination voulue n’est pas établie.</p></div></div><div class="note"><strong>Portée exacte :</strong> une manche, deux caméras fixes, annotations visuelles préparées par la même IA. Réglage sur les huit premiers lancers, puis code figé avant l’évaluation des huit suivants. Ce n’est pas un test indépendant sur une autre partie.</div>
<section id="throws"><p class="eyebrow">01 / Détection automatique</p><h2>Une pierre qui avance, pas une image de dessus.</h2><p>Le détecteur cherche une petite pierre rouge ou jaune, suit son déplacement et confirme son passage vers le haut de l’image à travers une ligne virtuelle. Il n’utilise ni les horaires annotés, ni un quota de 16 lancers, ni l’alternance des couleurs.</p><div class="video-wrap"><video id="video" src="end3.mp4" preload="metadata" playsinline muted></video><canvas id="overlay" width="1920" height="1080"></canvas></div><div class="controls"><button id="play">Lire / pause</button><input id="seek" type="range" min="0" max="1110" step="0.1" value="80" aria-label="Position dans la vidéo"><span id="clock" class="clock"></span><label>Vitesse <select id="speed"><option value="1">1×</option><option value="2">2×</option><option value="4">4×</option></select></label></div><div class="events" id="events"></div><p id="eventInfo"></p><p class="small">La ligne turquoise est un repère dans l’image, pas une ligne réglementaire. L’horodatage est celui du passage observé, pas celui du lâcher. Analyse à 10 Hz sur une copie 360p ; lecture de la source 1080p. Les rectangles suivent uniquement les observations disponibles, sans inventer de position pendant les occultations.</p><details><summary>Annotations et résultats, lancer par lancer</summary><div class="table-wrap"><table><thead><tr><th>Lancer</th><th>Intervalle annoté</th><th>Passage détecté</th><th>Évaluation</th><th>Preuve</th></tr></thead><tbody id="rows"></tbody></table></div><p>Annotations figées avant le détecteur : vues d’ensemble toutes les 5 s, puis séquences à 1 s autour des lancers. Les 16 prédictions tombent dans les intervalles de référence de 1 à 2 s. Cela ne mesure pas une erreur temporelle nulle. Un événement inhabituel très bref peut échapper à cette annotation exploratoire.</p><p>Première version : 7/8 lancers de développement. L’assouplissement du seuil de teinte rouge a récupéré une pierre sombre. Version figée : 8/8 en développement et 8/8 dans la seconde partie de la même manche.</p><p><a href="reference.json">Annotations figées</a> · <a href="evaluation.json">Évaluation</a> · <a href="predictions.json">Prédictions</a></p></details></section>
<section id="target"><p class="eyebrow">02 / Exemple du lancer 11</p><h2>Le balai est visible. L’intention reste à interpréter.</h2><div class="video-wrap"><video id="targetVideo" src="../continuous/clip.mp4" preload="metadata" playsinline muted></video><canvas id="targetOverlay" width="1920" height="1080"></canvas></div><div class="controls"><button id="targetPlay">Lire / pause</button><button data-jump="15">Balai avant le lancer</button><button data-jump="44">Départ</button><button data-jump="54">Arrivée et interaction</button><button data-jump="59">Stabilisation</button><span id="targetClock" class="clock"></span></div><div class="three"><article class="card"><h3>Avant</h3><p id="cueSummary"></p></article><article class="card"><h3>Pendant</h3><p>Une nouvelle trajectoire jaune à l’arrivée est associée au lancer par sa couleur, son mouvement et son ordre temporel. Association provisoire entre caméras.</p></article><article class="card"><h3>Après</h3><p id="settleSummary"></p></article></div><p class="small">Contour orange : candidat de tête de balai. Rectangle jaune : pierre reçue. Aucun contour n’est prolongé au-delà de ses observations. La détection du balai est une heuristique propre à cette source, sans reconnaissance générale du skip.</p><div class="note"><strong>Pourquoi aucun score en centimètres ?</strong> Le skip peut d’abord indiquer une destination, puis déplacer le balai pour donner une ligne de visée décalée. Dans cet exemple, la pierre interagit aussi avec une autre pierre. La distance finale au balai ne mesure donc pas la réussite du lancer. <a href="https://curlingdescollines.ca/index.php/en/41-curling-info/300-different-shots-signals">Explication des signaux</a>.</div><details><summary>Ce que la projection permet, et ce qu’elle ne prouve pas</summary><p>Le bas visible du balai peut être projeté sur la glace à condition qu’il soit réellement en contact avec elle. Les pierres utilisent le modèle conditionnel de hauteur existant. Les deux positions sont estimées ; aucune vérité terrain métrique indépendante n’est disponible pour cet extrait.</p><p>Le module de mesure refuse un score de distance si la destination n’est pas explicitement identifiée, si les repères sont incompatibles, ou si une collision rend la mesure inadaptée. Une coordonnée précise ne suffit pas à prouver l’intention.</p><p><a href="target-analysis.json">Observations et association</a> · <a href="evidence/target-context.jpg">Séquence visuelle avant et après</a></p></details></section>
<section><p class="eyebrow">03 / Pour mesurer la réussite d’un lancer</p><h2>Commencer par les placements clairement annoncés.</h2><div class="three"><article class="card"><h3>Placement / garde</h3><p>Identifier le geste indiquant la destination, puis comparer cette destination à la position finale de la pierre.</p></article><article class="card"><h3>Sortie de pierre</h3><p>Identifier la pierre visée et le résultat demandé : élimination, maintien ou déplacement latéral. Une simple distance ne suffit pas.</p></article><article class="card"><h3>Validation</h3><p>Faire annoter les intentions par une personne connaissant le curling, puis tester sur une autre partie et compter aussi les abstentions.</p></article></div><p><strong>Étape suivante concrète :</strong> annoter un petit ensemble de séquences avant lancer avec trois catégories : destination, ligne de visée, ambigu. Évaluer séparément détection des lancers, interprétation des gestes et position finale.</p><details><summary>Limites et reproduction</summary><p>La vue de départ et le sens de déplacement sont configurés manuellement. Une autre composition, un changement de sens, une reprise ou une pierre poussée à la main peut invalider cette méthode. La fiabilité générale n’est pas établie. Les 54 tests logiciels réussis vérifient le comportement du code, pas la précision sur de nouvelles vidéos.</p><p><a href="README.md">Méthode et commandes</a> · <a href="tests.txt">Tests</a> · <a href="../body-localization/index.html">Localisation des pierres</a></p></details></section><footer>Les vidéos et annotations restent des éléments de recherche locaux. Aucune modification des anciens bancs d’essai.</footer></main><script>
const pred=__PRED__,evaluation=__EVAL__,reference=__REF__,target=__TARGET__;const v=document.getElementById('video'),can=document.getElementById('overlay'),ctx=can.getContext('2d'),tv=document.getElementById('targetVideo'),tc=document.getElementById('targetOverlay').getContext('2d');let selected=0;function stamp(t){let m=Math.floor(t/60);return m+':'+(t%60).toFixed(1).padStart(4,'0')}
const buttons=document.getElementById('events');pred.events.forEach((e,i)=>{let b=document.createElement('button');b.textContent=String(i+1).padStart(2,'0');b.className=e.colour==='yellow'?'yellow':'';b.setAttribute('aria-label','Lancer '+(i+1));b.onclick=()=>select(i);buttons.appendChild(b)});function select(i){selected=i;let e=pred.events[i];v.currentTime=Math.max(0,e.crossing_time_s-1650-4);[...buttons.children].forEach((b,j)=>b.classList.toggle('active',i===j));document.getElementById('eventInfo').textContent=`Lancer ${i+1} · ${e.colour==='yellow'?'jaune':'rouge'} · passage à ${stamp(e.crossing_time_s)} · ${i<8?'développement':'vérification dans la même manche'}`;draw()}
function box(c,p,color,scale=1){if(!p)return;c.strokeStyle=color;c.lineWidth=4;let b=p.bbox;c.strokeRect(b[0]*scale,b[1]*scale,b[2]*scale,b[3]*scale)}
function draw(){let t=1650+v.currentTime;ctx.clearRect(0,0,1920,1080);ctx.strokeStyle='#3fe1d2';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(120,180);ctx.lineTo(840,180);ctx.stroke();for(let e of pred.events){let pts=e.trajectory.filter(p=>p.time_s<=t&&t-p.time_s<=1);if(!pts.length||t-pts[pts.length-1].time_s>.16)continue;let p=pts[pts.length-1];box(ctx,p,e.colour==='yellow'?'#ffe052':'#ff725d',3);ctx.beginPath();pts.forEach((p,i)=>i?ctx.lineTo(p.pixel[0]*3,p.pixel[1]*3):ctx.moveTo(p.pixel[0]*3,p.pixel[1]*3));ctx.stroke()}document.getElementById('clock').textContent=stamp(t)+' source';document.getElementById('seek').value=v.currentTime}
v.addEventListener('timeupdate',draw);v.addEventListener('seeked',draw);document.getElementById('play').onclick=()=>v.paused?v.play():v.pause();document.getElementById('seek').oninput=e=>v.currentTime=+e.target.value;document.getElementById('speed').onchange=e=>v.playbackRate=+e.target.value;v.addEventListener('loadedmetadata',()=>select(0),{once:true});
reference.events.forEach((r,i)=>{let e=pred.events[i];let tr=document.createElement('tr');[r.id,r.crossing_interval_s.map(stamp).join(' à '),stamp(e.crossing_time_s),i<8?'Développement':'Même manche'].forEach(txt=>{let td=document.createElement('td');td.textContent=txt;tr.appendChild(td)});let td=document.createElement('td');let a=document.createElement('a');a.href=r.evidence;a.textContent='Images annotées';td.appendChild(a);tr.appendChild(td);document.getElementById('rows').appendChild(tr)});
const example=target.examples[0];document.getElementById('cueSummary').textContent=`Un candidat de balai stable sur ${example.broom_cue.stable_observations} observations, pendant ${(example.broom_cue.span_s[1]-example.broom_cue.span_s[0]).toFixed(1)} s avant le passage.`;document.getElementById('settleSummary').textContent=`Stabilisation visuelle proposée à ${stamp(example.outcome.settled.time_s)}, après 2 s de faible mouvement. Une interaction est signalée près de ${example.outcome.interaction_candidates.length?stamp(example.outcome.interaction_candidates[0].time_s):'un instant non déterminé'}. Ce n’est pas une qualification automatique du lancer.`;
function drawTarget(){let t=tv.currentTime,src=2260+t;tc.clearRect(0,0,1920,1080);let r=target.records[Math.floor(t*2)];if(r&&Math.abs(r.time_s-t)<.55)r.candidates.forEach(p=>box(tc,p,'#ffab39'));let pts=example.outcome.trajectory.filter(p=>p.time_s<=src&&src-p.time_s<=2);if(pts.length&&src-pts[pts.length-1].time_s<.55){tc.strokeStyle='#ffe052';tc.lineWidth=4;tc.beginPath();pts.forEach((p,i)=>i?tc.lineTo(...p.pixel):tc.moveTo(...p.pixel));tc.stroke();let p=pts[pts.length-1];tc.strokeRect(p.pixel[0]-28,p.pixel[1]-16,56,40)}document.getElementById('targetClock').textContent=stamp(src)+' source'}tv.addEventListener('timeupdate',drawTarget);tv.addEventListener('seeked',drawTarget);tv.addEventListener('loadedmetadata',()=>tv.currentTime=15,{once:true});document.getElementById('targetPlay').onclick=()=>tv.paused?tv.play():tv.pause();document.querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>tv.currentTime=+b.dataset.jump);
</script><p><a href="../trajectory-accuracy/">Trajectoire en vue de dessus et première mesure de localisation</a></p><p><a href="../throw-segments/index.html">Découpage par lancer et suivi des arrivées</a></p></body></html>"""
for k, v in [("PRED", pred), ("EVAL", evaluation), ("REF", ref), ("TARGET", target)]:
    body = body.replace("__" + k + "__", json.dumps(v, ensure_ascii=False).replace("</", "<\\/"))
(out / "index.html").write_text(body)
print("Built", out / "index.html")
